import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

/**
 * Packages SAP Business One Extension Manager (.mtar) archives in mta_archives/
 * using the exact module/data.zip + META-INF/MANIFEST.MF structure generated by
 * SAP Cloud MTA Build Tool (mbt / SAP Application Archive Builder):
 *
 *   1. pt-bank-reconciliation_1.0.0.mtar
 *      -> type: single-page-app (deploy_mode: b1-webclient)
 *      -> contains META-INF/MANIFEST.MF, META-INF/mtad.yaml, and webclient/data.zip
 *   2. pt-bank-reconciliation-url-mashup_1.0.0.mtar
 *      -> type: url-mashup (deploy_mode: b1-webclient)
 *      -> contains META-INF/MANIFEST.MF, META-INF/mtad.yaml, and urlMashup/data.zip
 */
const rootDir = process.cwd();
const frontendDist = path.join(rootDir, 'packages/frontend/dist');
const outDir = path.join(rootDir, 'mta_archives');
const backendPublicUrl = process.env.BACKEND_PUBLIC_URL || 'http://localhost:4010';

if (!fs.existsSync(frontendDist)) {
  console.error('Error: packages/frontend/dist does not exist. Run "npm run build" first.');
  process.exit(1);
}

// Clean old archives
fs.rmSync(outDir, { recursive: true, force: true });
fs.mkdirSync(outDir, { recursive: true });

// ---------------------------------------------------------------------------
// 1. Build Single-Page-App (.mtar) with webclient/data.zip
// ---------------------------------------------------------------------------
const spaStaging = path.join(outDir, '.staging-spa');
const spaMtarPath = path.join(outDir, 'pt-bank-reconciliation_1.0.0.mtar');

fs.mkdirSync(path.join(spaStaging, 'META-INF'), { recursive: true });
fs.mkdirSync(path.join(spaStaging, 'webclient'), { recursive: true });

// Zip the contents of packages/frontend/dist into webclient/data.zip (required by SAP B1 ui-static)
const spaDataZipPath = path.join(spaStaging, 'webclient/data.zip');
execFileSync('zip', ['-r', '-q', spaDataZipPath, '.'], { cwd: frontendDist });

const spaMtadYaml = `_schema-version: "3.2"
ID: pt-company-b1-bankreconciliation
description: SAP Business One Web Client Extension — Reconciliação Bancária (SWIFT
  MT940 & Norma 43)
version: 1.0.0
provider: SAP
modules:
- name: webclient
  type: single-page-app
  path: webclient
  parameters:
    deploy_mode: b1-webclient
`;

const spaManifestMf = [
  'manifest-Version: 1.0',
  'Created-By: SAP Application Archive Builder 1.2.53',
  '',
  'Name: webclient/data.zip',
  'MTA-Module: webclient',
  'Content-Type: application/zip',
  '',
  '',
  'Name: META-INF/mtad.yaml',
  'Content-Type: text/plain',
  '',
].join('\n');

fs.writeFileSync(path.join(spaStaging, 'META-INF/mtad.yaml'), spaMtadYaml, 'utf8');
fs.writeFileSync(path.join(spaStaging, 'META-INF/MANIFEST.MF'), spaManifestMf, 'utf8');

execFileSync('zip', ['-r', '-q', spaMtarPath, 'META-INF', 'webclient'], { cwd: spaStaging });
fs.rmSync(spaStaging, { recursive: true, force: true });

// ---------------------------------------------------------------------------
// 2. Build URL-Mashup (.mtar) with urlMashup/data.zip
// ---------------------------------------------------------------------------
const mashupStaging = path.join(outDir, '.staging-mashup');
const mashupPayloadDir = path.join(mashupStaging, '.payload');
const mashupMtarPath = path.join(outDir, 'pt-bank-reconciliation-url-mashup_1.0.0.mtar');

fs.mkdirSync(path.join(mashupStaging, 'META-INF'), { recursive: true });
fs.mkdirSync(path.join(mashupStaging, 'urlMashup'), { recursive: true });
fs.mkdirSync(mashupPayloadDir, { recursive: true });

const mashupExtensionJson = {
  tiles: [
    {
      text: 'Reconciliação Bancária',
      subtitle: 'SWIFT MT940 • Norma 43',
      icon: 'sap-icon://money-bills',
      url: `${backendPublicUrl.replace(/\/+$/, '')}/?companyID={b1-companyID}`,
      linkmethod: 'ExistingWindow',
      size: '1x1',
    },
  ],
};

fs.writeFileSync(
  path.join(mashupPayloadDir, 'WebClientExtension.json'),
  JSON.stringify(mashupExtensionJson, null, 2),
  'utf8'
);

const mashupDataZipPath = path.join(mashupStaging, 'urlMashup/data.zip');
execFileSync('zip', ['-r', '-q', mashupDataZipPath, '.'], { cwd: mashupPayloadDir });
fs.rmSync(mashupPayloadDir, { recursive: true, force: true });

const mashupMtadYaml = `_schema-version: "3.2"
ID: pt-company-b1-bankreconciliation-mashup
description: SAP Business One Web Client URL Mashup — Reconciliação Bancária (SWIFT
  MT940 & Norma 43)
version: 1.0.0
provider: SAP
modules:
- name: urlMashup
  type: url-mashup
  path: urlMashup
  parameters:
    deploy_mode: b1-webclient
`;

const mashupManifestMf = [
  'manifest-Version: 1.0',
  'Created-By: SAP Application Archive Builder 1.2.53',
  '',
  'Name: urlMashup/data.zip',
  'MTA-Module: urlMashup',
  'Content-Type: application/zip',
  '',
  '',
  'Name: META-INF/mtad.yaml',
  'Content-Type: text/plain',
  '',
].join('\n');

fs.writeFileSync(path.join(mashupStaging, 'META-INF/mtad.yaml'), mashupMtadYaml, 'utf8');
fs.writeFileSync(path.join(mashupStaging, 'META-INF/MANIFEST.MF'), mashupManifestMf, 'utf8');

execFileSync('zip', ['-r', '-q', mashupMtarPath, 'META-INF', 'urlMashup'], { cwd: mashupStaging });
fs.rmSync(mashupStaging, { recursive: true, force: true });

console.log(`Built Single-Page-App MTAR: ${spaMtarPath}`);
console.log(`Built URL-Mashup MTAR (${backendPublicUrl}): ${mashupMtarPath}`);
